-- After 07, read as the agent user: IBM's functions its grantees (itself and PUBLIC here, it holds no group or role)
-- may execute whose own catalog row reads EXTERNAL_ACTION E or SQL_DATA_ACCESS M. Each is on the check's list of
-- functions measured as reading only (reading-functions.ts), which a unit test holds equal to this answer. Then the
-- modules they may execute holding such a function, none once 07 ran, and a sample of the listed functions called in
-- the derived table the agent's statement is sent in: each answers or is refused by its own authority check.
SELECT VARCHAR(r.ROUTINESCHEMA, 8) AS ROUTINESCHEMA, VARCHAR(r.SPECIFICNAME, 30) AS SPECIFICNAME, r.EXTERNAL_ACTION, r.SQL_DATA_ACCESS FROM SYSCAT.ROUTINEAUTH a JOIN SYSCAT.ROUTINES r ON r.ROUTINESCHEMA = a.SCHEMA AND (r.SPECIFICNAME = a.SPECIFICNAME OR a.SPECIFICNAME IS NULL AND r.ROUTINETYPE = a.ROUTINETYPE) WHERE (a.GRANTEE, a.GRANTEETYPE) IN (VALUES (CAST(SESSION_USER AS VARCHAR(128)), CAST('U' AS CHAR(1))), (CAST('PUBLIC' AS VARCHAR(128)), CAST('G' AS CHAR(1)))) AND a.EXECUTEAUTH <> 'N' AND r.OWNERTYPE = 'S' AND r.ROUTINETYPE IN ('F', 'M') AND (r.EXTERNAL_ACTION = 'E' OR r.SQL_DATA_ACCESS = 'M') ORDER BY 1, 2;
SELECT VARCHAR(m.MODULESCHEMA, 10) AS MODULESCHEMA, VARCHAR(m.MODULENAME, 22) AS MODULENAME, COUNT(*) AS FUNCTIONS FROM SYSCAT.MODULEAUTH m JOIN SYSCAT.ROUTINES r ON r.ROUTINEMODULEID = m.MODULEID WHERE m.GRANTEE IN (SESSION_USER, 'PUBLIC') AND m.EXECUTEAUTH <> 'N' AND r.ROUTINETYPE IN ('F', 'M') AND (r.EXTERNAL_ACTION = 'E' OR r.SQL_DATA_ACCESS = 'M') GROUP BY m.MODULESCHEMA, m.MODULENAME ORDER BY 1, 2;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.DB_MEMBERS()) AS T) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.DB_PARTITIONS()) AS T) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.ADMIN_LIST_HIST()) AS T) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.HEALTH_DB_INFO('', -1)) AS T) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT VARCHAR(SYSPROC.GET_INDEX_COLNAMES('APP', 'ORDERS'), 40) AS C FROM SYSIBM.SYSDUMMY1) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.SNAP_GET_DB('', -1)) AS T) AS LIBREDB_AGENT_READ;
SELECT * FROM (SELECT COUNT(*) AS N FROM TABLE (SYSPROC.SNAP_GET_TAB('', -1)) AS T) AS LIBREDB_AGENT_READ;
